#include <cstddef>

// remaining: return how many items are left after removing 'taken' from 'total'.
// If taken > total, the answer is 0 -- nothing left.
//
// BUG: std::size_t is unsigned; when taken > total the subtraction
// wraps around to a huge value instead of going negative.
std::size_t remaining(std::size_t total, std::size_t taken) {
    return total - taken;  // BUG: wraps when taken > total
}

