    CHECK(remaining(5,  5)  == 0);   // exactly depleted
    CHECK(remaining(0,  0)  == 0);
    CHECK(remaining(3, 10)  == 0);   // taken > total: clamp to 0, not a wrap
    CHECK(remaining(1,  2)  == 0);   // taken > total: clamp to 0
    if (!fails) std::cout << "PASS\n";
    return fails ? 1 : 0;
}

drills.solution:
#include <cstddef>

std::size_t remaining(std::size_t total, std::size_t taken) {
    if (taken >= total)
    {
        return 0;
    }
    return total - taken;
}
